import React, { useState } from 'react';
import './Metas.css';

const Metas = () => {
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [investmentAmount, setInvestmentAmount] = useState('');
  const [calculatedReturn, setCalculatedReturn] = useState(null);
  const [investmentHistory, setInvestmentHistory] = useState([]);

  const plans = [
    { name: 'Mercado de Acciones', rate: 0.07 },
    { name: 'Bonos', rate: 0.03 },
    { name: 'Fondos de Inversión', rate: 0.05 },
  ];

  const handlePlanSelect = (plan) => {
    setSelectedPlan(plan);
  };

  const handleInvestmentChange = (e) => {
    setInvestmentAmount(e.target.value);
  };

  const calculateReturn = () => {
    if (investmentAmount && selectedPlan) {
      const returnAmount = investmentAmount * (1 + selectedPlan.rate);
      setCalculatedReturn(returnAmount.toFixed(2));

      // Guardar la inversión en el historial
      const investmentRecord = {
        plan: selectedPlan.name,
        amount: investmentAmount,
        return: returnAmount.toFixed(2),
      };
      setInvestmentHistory([...investmentHistory, investmentRecord]);
      setInvestmentAmount(''); // Reiniciar el campo de entrada
      setSelectedPlan(null); // Reiniciar la selección de plan
    }
  };

  return (
    <div className="metas-container">
      <h1>Metas de Inversión y Tasas de Interés</h1>

      {/* Secciones de tasas de interés y planes de inversión aquí... */}

      <section className="investment-calculator">
        <h2>Calculadora de Rendimiento</h2>
        <input
          type="number"
          value={investmentAmount}
          onChange={handleInvestmentChange}
          placeholder="Monto a invertir"
        />
        <button onClick={calculateReturn}>Calcular Rendimiento</button>
        {calculatedReturn && (
          <p>El rendimiento esperado de su inversión es: ${calculatedReturn}</p>
        )}
      </section>

      {/* Sección de Historial de Inversiones */}
      <section className="investment-history">
        <h2>Historial de Inversiones</h2>
        <table>
          <thead>
            <tr>
              <th>Plan</th>
              <th>Monto Invertido</th>
              <th>Rendimiento Esperado</th>
            </tr>
          </thead>
          <tbody>
            {investmentHistory.map((investment, index) => (
              <tr key={index}>
                <td>{investment.plan}</td>
                <td>${investment.amount}</td>
                <td>${investment.return}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      <div className="cta-container">
        <p>¿Listo para invertir y alcanzar tus metas?</p>
        <button className="cta-button">Obtener Más Información</button>
      </div>
    </div>
  );
};

export default Metas;
